-- rowstile 0.1.0-dev: sync_due_times. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', 'a8e8f8e5bfc35f34', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'a8e8f8e5bfc35f34' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'a8e8f8e5bfc35f34' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = 'a8e8f8e5bfc35f34' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM '7ce75c6b1593a2ba' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      '7ce75c6b1593a2ba', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'hd_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- The sync index (a preview): who may read each row of the synced tables, as keys, and the keys each principal
-- holds. Kept across applies: the sync engines keep their shapes on these tables
CREATE SCHEMA IF NOT EXISTS authz_sync;
REVOKE ALL ON SCHEMA authz_sync FROM PUBLIC;
-- tables this policy doesn't keep, and a readers table whose key columns are not the type's any more, go
DO $sb$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_catalog.pg_class c
           LEFT JOIN (VALUES ('keys', ARRAY['principal_type', 'principal_id', 'key']::name[], ARRAY['text', 'text', 'text']::regtype[]),
             ('groups', ARRAY['grp', 'key']::name[], ARRAY['text', 'text']::regtype[]),
             ('expanded', ARRAY['object_type', 'object_id', 'key']::name[], ARRAY['text', 'text', 'text']::regtype[]),
             ('definitions', ARRAY['name', 'hash']::name[], ARRAY['text', 'text']::regtype[]),
             ('due', ARRAY['object_type', 'object_id', 'at']::name[], ARRAY['text', 'text', 'timestamp with time zone']::regtype[]),
             ('ticket__readers', ARRAY['id', 'key']::name[], ARRAY['uuid', 'text']::regtype[]),
             ('comment__readers', ARRAY['id', 'key']::name[], ARRAY['uuid', 'text']::regtype[])) w(name, cols, types) ON w.name = c.relname
           WHERE c.relnamespace = 'authz_sync'::regnamespace AND c.relkind IN ('r', 'p')
             AND (w.name IS NULL
                  OR w.cols IS NOT NULL AND (
                    (SELECT array_agg(a.attname ORDER BY a.attnum) FROM pg_catalog.pg_attribute a
                     WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped) IS DISTINCT FROM w.cols
                    OR (SELECT array_agg(a.atttypid::regtype ORDER BY a.attnum) FROM pg_catalog.pg_attribute a
                        WHERE a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped) IS DISTINCT FROM w.types)) LOOP
    EXECUTE format('DROP TABLE %s', r.tbl);
  END LOOP;
  -- a table missing (dropped since, or just now): what the index holds is worked out again (sync_refresh)
  IF to_regclass('authz_sync.definitions') IS NOT NULL AND EXISTS (
       SELECT 1 FROM (VALUES ('keys', ARRAY['principal_type', 'principal_id', 'key']::name[], ARRAY['text', 'text', 'text']::regtype[]),
             ('groups', ARRAY['grp', 'key']::name[], ARRAY['text', 'text']::regtype[]),
             ('expanded', ARRAY['object_type', 'object_id', 'key']::name[], ARRAY['text', 'text', 'text']::regtype[]),
             ('definitions', ARRAY['name', 'hash']::name[], ARRAY['text', 'text']::regtype[]),
             ('due', ARRAY['object_type', 'object_id', 'at']::name[], ARRAY['text', 'text', 'timestamp with time zone']::regtype[]),
             ('ticket__readers', ARRAY['id', 'key']::name[], ARRAY['uuid', 'text']::regtype[]),
             ('comment__readers', ARRAY['id', 'key']::name[], ARRAY['uuid', 'text']::regtype[])) w(name, cols, types)
       WHERE w.cols IS NOT NULL AND to_regclass(pg_catalog.format('authz_sync.%I', w.name)) IS NULL) THEN
    DELETE FROM authz_sync.definitions;
  END IF;
END $sb$;
-- the keys each principal holds: its own (user:42), every one of its type's (user:*), anyone's, and its groups'
CREATE TABLE IF NOT EXISTS authz_sync.keys (principal_type text NOT NULL, principal_id text NOT NULL, key text NOT NULL,
  PRIMARY KEY (principal_type, principal_id, key));
CREATE INDEX IF NOT EXISTS keys_by_key ON authz_sync.keys (key);
ALTER TABLE authz_sync.keys REPLICA IDENTITY FULL;
-- the keys that make up each group key (team#member:10): a principal holding one holds the group's
CREATE TABLE IF NOT EXISTS authz_sync.groups (grp text NOT NULL, key text NOT NULL, PRIMARY KEY (grp, key));
CREATE INDEX IF NOT EXISTS groups_by_key ON authz_sync.groups (key);
ALTER TABLE authz_sync.groups REPLICA IDENTITY FULL;
-- the keys a row's readers were worked out from, where they are principals (an and / not between groups)
CREATE TABLE IF NOT EXISTS authz_sync.expanded (object_type text NOT NULL, object_id text NOT NULL, key text NOT NULL,
  PRIMARY KEY (object_type, object_id, key));
CREATE INDEX IF NOT EXISTS expanded_by_key ON authz_sync.expanded (key);
ALTER TABLE authz_sync.expanded REPLICA IDENTITY FULL;
-- what the rows were worked out by: an apply that changes it works them out again (by difference)
CREATE TABLE IF NOT EXISTS authz_sync.definitions (name text PRIMARY KEY, hash text NOT NULL);
ALTER TABLE authz_sync.definitions REPLICA IDENTITY FULL;
-- for each object with a share that starts or ends later: the next such time after its readers were last worked out,
-- when authz.sync_tick() works them out again
CREATE TABLE IF NOT EXISTS authz_sync.due (object_type text NOT NULL, object_id text NOT NULL, at timestamptz NOT NULL,
  PRIMARY KEY (object_type, object_id));
CREATE INDEX IF NOT EXISTS due_by_at ON authz_sync.due (at);
ALTER TABLE authz_sync.due REPLICA IDENTITY FULL;
-- (what an earlier authz.sync_tick() kept: the end of its last run, read no more)
DELETE FROM authz.settings WHERE key = 'sync_tick_to';
CREATE TABLE IF NOT EXISTS authz_sync."ticket__readers" ("id" uuid NOT NULL, key text NOT NULL, PRIMARY KEY ("id", key));
CREATE INDEX IF NOT EXISTS "ticket__readers_key" ON authz_sync."ticket__readers" (key);
ALTER TABLE authz_sync."ticket__readers" REPLICA IDENTITY FULL;
CREATE TABLE IF NOT EXISTS authz_sync."comment__readers" ("id" uuid NOT NULL, key text NOT NULL, PRIMARY KEY ("id", key));
CREATE INDEX IF NOT EXISTS "comment__readers_key" ON authz_sync."comment__readers" (key);
ALTER TABLE authz_sync."comment__readers" REPLICA IDENTITY FULL;
REVOKE ALL ON ALL TABLES IN SCHEMA authz_sync FROM PUBLIC;

-- The index made current for the objects a transaction changed and what reads them (the difference written, not
-- every row again): at its commit, in it, or after it, by the worker. The groups first, then the keys (a principal
-- holds the keys of every group whose members hold one of its own, through groups inside groups), then the readers
-- (JIT off: its statements read a few rows each, through indexes, which a plan made for many would compile for; no
-- merge joins: its sets of keys, which the planner can't count, are joined by hash, not sorted as text)
CREATE OR REPLACE FUNCTION authz_int.sync_process() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT SET jit = off SET enable_mergejoin = off AS $f$
DECLARE
  v_tx bigint := txid_current();
  v_round int;
  v_mode int[]; v_w int[]; v_r int[]; v_s int; v_x boolean;
  v_ids text[]; v_part text[]; v_from int; v_now text[];
  v_keys text[] := '{}';     -- the keys a principal gained or lost
  v_came text[] := '{}';     -- the principals who are somebody now, and held no key (type:id)
  v_whole text[] := '{}';    -- the principal types worked out whole
  v_keys_locked boolean := false;
  v_all boolean;               -- every principal's keys worked out whole (applying): the groups' changes aren't followed
  v_n bigint;
  v_found int;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx) THEN RETURN; END IF;
  -- one lock row for every commit's work: what an `and` or `not` between parts that depend on who asks
  -- gives is worked out from the keys, which any change may move. In REPEATABLE READ or SERIALIZABLE, a
  -- writer whose snapshot is older than another's index write gets a serialization error
  UPDATE authz_int.locks SET n = n + 1 WHERE type = 'sync#keys';
  v_keys_locked := true;
  v_round := authz_int.sync_spread(v_tx, 0);
  v_all := (SELECT count(DISTINCT x.type) FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id = '*'
            AND x.type = ANY (ARRAY['user', 'integration']::text[])) = 2;
  -- team's groups
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'team' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "hd"."teams" x UNION SELECT x."team_id"::text FROM "hd"."team_members" x UNION SELECT x."team_id"::text FROM "hd"."team_leads" x UNION SELECT g.object_id FROM authz.shares g WHERE g.object_type = 'team' UNION SELECT substr(g.grp, strpos(g.grp, ':') + 1) FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) = ANY (ARRAY['team#member:', 'team#oversee:']::text[])) ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'team') END;
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
      WITH fresh AS MATERIALIZED (SELECT 'team#member:' || f.o_id::text AS grp, f.o_key AS key FROM authz_int."sync:team.member"(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f WHERE NOT f.o_dep),
      gone AS (DELETE FROM authz_sync.groups g WHERE g.grp IN (SELECT 'team#member:' || v FROM unnest(v_part) v)
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.grp = g.grp AND f.key = g.key) RETURNING g.grp, g.key),
      made AS (INSERT INTO authz_sync.groups SELECT f.grp, f.key FROM fresh f ON CONFLICT DO NOTHING RETURNING grp, key)
      INSERT INTO authz_int.sync_moved SELECT v_tx, z.grp, z.key, z.made
      FROM (SELECT grp, key, false AS made FROM gone UNION ALL SELECT grp, key, true FROM made) z
      WHERE NOT v_all;
      WITH fresh AS MATERIALIZED (SELECT 'team#oversee:' || f.o_id::text AS grp, f.o_key AS key FROM authz_int."sync:team.oversee"(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f WHERE NOT f.o_dep),
      gone AS (DELETE FROM authz_sync.groups g WHERE g.grp IN (SELECT 'team#oversee:' || v FROM unnest(v_part) v)
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.grp = g.grp AND f.key = g.key) RETURNING g.grp, g.key),
      made AS (INSERT INTO authz_sync.groups SELECT f.grp, f.key FROM fresh f ON CONFLICT DO NOTHING RETURNING grp, key)
      INSERT INTO authz_int.sync_moved SELECT v_tx, z.grp, z.key, z.made
      FROM (SELECT grp, key, false AS made FROM gone UNION ALL SELECT grp, key, true FROM made) z
      WHERE NOT v_all;
  END LOOP;
  -- the keys, where the groups' rows or the principals changed: under one lock row, taken last (nothing after it waits
  -- for another lock)
  IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx)
     OR EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = ANY (ARRAY['user', 'integration']::text[])) THEN
    IF NOT v_keys_locked THEN
      UPDATE authz_int.locks SET n = n + 1 WHERE type = 'sync#keys';
    END IF;
    -- the principals of user: every one worked out whole (applying), or those that changed: one who is
    -- nobody now (gone, or failing the type's where) holds no key, and one who is somebody now and held none gets theirs
    IF EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'user' AND x.id = '*') THEN
      v_whole := v_whole || 'user'::text;
      v_ids := ARRAY(SELECT x."id"::text FROM "hd"."users" x UNION SELECT k.principal_id FROM authz_sync.keys k WHERE k.principal_type = 'user');
      WITH fresh AS MATERIALIZED (SELECT * FROM authz_int."sync_keys:user"(v_ids)),
      gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id IN (SELECT unnest(v_ids))
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_id = k.principal_id AND f.o_key = k.key) RETURNING k.key),
      made AS (INSERT INTO authz_sync.keys SELECT 'user', f.o_id, f.o_key FROM fresh f ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.k), '{}') INTO v_keys FROM (SELECT key FROM gone UNION SELECT key FROM made) z(k);
    ELSE
      v_ids := ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'user');
      IF cardinality(v_ids) > 0 THEN
        v_now := ARRAY(SELECT x."id"::text FROM "hd"."users" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(v_ids) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid')))) AND coalesce((active), false));
        WITH gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id = ANY (v_ids)
                      AND k.principal_id <> ALL (v_now) RETURNING k.key)
        SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
        v_came := v_came || ARRAY(SELECT 'user' || ':' || v FROM unnest(v_now) v WHERE NOT EXISTS (
          SELECT 1 FROM authz_sync.keys k WHERE k.principal_type = 'user' AND k.principal_id = v));
      END IF;
    END IF;
    -- the principals of integration: every one worked out whole (applying), or those that changed: one who is
    -- nobody now (gone, or failing the type's where) holds no key, and one who is somebody now and held none gets theirs
    IF EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'integration' AND x.id = '*') THEN
      v_whole := v_whole || 'integration'::text;
      v_ids := ARRAY(SELECT x."id"::text FROM "hd"."integrations" x UNION SELECT k.principal_id FROM authz_sync.keys k WHERE k.principal_type = 'integration');
      WITH fresh AS MATERIALIZED (SELECT * FROM authz_int."sync_keys:integration"(v_ids)),
      gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'integration' AND k.principal_id IN (SELECT unnest(v_ids))
               AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_id = k.principal_id AND f.o_key = k.key) RETURNING k.key),
      made AS (INSERT INTO authz_sync.keys SELECT 'integration', f.o_id, f.o_key FROM fresh f ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.k), '{}') INTO v_keys FROM (SELECT key FROM gone UNION SELECT key FROM made) z(k);
    ELSE
      v_ids := ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'integration');
      IF cardinality(v_ids) > 0 THEN
        v_now := ARRAY(SELECT x."id"::text FROM "hd"."integrations" x WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(v_ids) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid')))) AND coalesce((active), false));
        WITH gone AS (DELETE FROM authz_sync.keys k WHERE k.principal_type = 'integration' AND k.principal_id = ANY (v_ids)
                      AND k.principal_id <> ALL (v_now) RETURNING k.key)
        SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
        v_came := v_came || ARRAY(SELECT 'integration' || ':' || v FROM unnest(v_now) v WHERE NOT EXISTS (
          SELECT 1 FROM authz_sync.keys k WHERE k.principal_type = 'integration' AND k.principal_id = v));
      END IF;
    END IF;
    -- a group's row gone: the keys above it that its member's holders held may go, unless what is left gives them
    -- again (each found given is taken back from those that may go, as often as it finds more)
    IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx AND NOT m.made) THEN
      WITH RECURSIVE up(src, c) AS (
        SELECT DISTINCT m.key, m.grp FROM authz_int.sync_moved m WHERE m.txid = v_tx AND NOT m.made
        UNION
        SELECT up.src, g.grp FROM up JOIN authz_sync.groups g ON g.key = up.c)
      -- (the holders of each key, a lookup by the keys' index: OFFSET 0 keeps the planner from reading every key for a
      -- few; then the sets joined whole)
      , by_src AS MATERIALIZED (
        SELECT DISTINCT up.c, k.principal_type AS pt, k.principal_id AS pid FROM up
        CROSS JOIN LATERAL (SELECT k.principal_type, k.principal_id FROM authz_sync.keys k WHERE k.key = up.src
                            AND k.principal_type <> ALL (v_whole) OFFSET 0) k),
      by_c AS MATERIALIZED (
        SELECT c.c, h.principal_type AS pt, h.principal_id AS pid FROM (SELECT DISTINCT up.c FROM up) c
        CROSS JOIN LATERAL (SELECT h.principal_type, h.principal_id FROM authz_sync.keys h WHERE h.key = c.c OFFSET 0) h)
      INSERT INTO authz_int.sync_lost (txid, ptype, pid, key)
      SELECT v_tx, s.pt, s.pid, s.c FROM by_src s JOIN by_c h ON h.c = s.c AND h.pt = s.pt AND h.pid = s.pid
      ON CONFLICT DO NOTHING;
      -- given again: by a member it holds that may not go (the holders of the members of the groups that may go, once
      -- each); then, round by round, by a member just found given
      WITH members AS MATERIALIZED (
        SELECT g.grp, g.key FROM (SELECT DISTINCT l.key FROM authz_int.sync_lost l WHERE l.txid = v_tx) c
        CROSS JOIN LATERAL (SELECT g.grp, g.key FROM authz_sync.groups g WHERE g.grp = c.key OFFSET 0) g),
      held AS MATERIALIZED (
        SELECT m.key, h.principal_type AS pt, h.principal_id AS pid FROM (SELECT DISTINCT key FROM members) m
        CROSS JOIN LATERAL (SELECT h.principal_type, h.principal_id FROM authz_sync.keys h WHERE h.key = m.key OFFSET 0) h),
      -- (the groups each holder holds a member of, that may not go; then the candidates they give again)
      supported AS MATERIALIZED (
        SELECT DISTINCT g.grp, h.pt, h.pid FROM members g JOIN held h ON h.key = g.key
        WHERE NOT EXISTS (SELECT 1 FROM authz_int.sync_lost o WHERE o.txid = v_tx AND o.ptype = h.pt AND o.pid = h.pid
                          AND o.key = h.key)),
      given AS (SELECT l.ptype, l.pid, l.key FROM authz_int.sync_lost l
                JOIN supported s ON s.grp = l.key AND s.pt = l.ptype AND s.pid = l.pid WHERE l.txid = v_tx),
      r AS (DELETE FROM authz_int.sync_lost l USING given z WHERE l.txid = v_tx AND l.ptype = z.ptype AND l.pid = z.pid
            AND l.key = z.key RETURNING l.ptype, l.pid, l.key)
      INSERT INTO authz_int.sync_found SELECT v_tx, r.ptype, r.pid, r.key, 1 FROM r;
      GET DIAGNOSTICS v_n = ROW_COUNT;
      v_found := 1;
      WHILE v_n > 0 LOOP
        WITH r AS (DELETE FROM authz_int.sync_lost l
                   USING (SELECT DISTINCT f.ptype, f.pid, g.grp FROM authz_int.sync_found f
                          JOIN authz_sync.groups g ON g.key = f.key WHERE f.txid = v_tx AND f.round = v_found) z
                   WHERE l.txid = v_tx AND l.ptype = z.ptype AND l.pid = z.pid AND l.key = z.grp
                   RETURNING l.ptype, l.pid, l.key)
        INSERT INTO authz_int.sync_found SELECT v_tx, r.ptype, r.pid, r.key, v_found + 1 FROM r;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        v_found := v_found + 1;
      END LOOP;
      DELETE FROM authz_int.sync_found f WHERE f.txid = v_tx;
      WITH gone AS (DELETE FROM authz_sync.keys k USING authz_int.sync_lost l WHERE l.txid = v_tx
                    AND k.principal_type = l.ptype AND k.principal_id = l.pid AND k.key = l.key RETURNING k.key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM gone z;
      DELETE FROM authz_int.sync_lost l WHERE l.txid = v_tx;
    END IF;
    -- a group's row made: its member's holders hold the group, and the groups above it
    IF EXISTS (SELECT 1 FROM authz_int.sync_moved m WHERE m.txid = v_tx AND m.made) THEN
      WITH RECURSIVE up(src, c) AS (
        SELECT DISTINCT m.key, m.grp FROM authz_int.sync_moved m WHERE m.txid = v_tx AND m.made
        UNION
        SELECT up.src, g.grp FROM up JOIN authz_sync.groups g ON g.key = up.c),
      made AS (INSERT INTO authz_sync.keys SELECT DISTINCT k.principal_type, k.principal_id, up.c FROM up
               CROSS JOIN LATERAL (SELECT k.principal_type, k.principal_id FROM authz_sync.keys k WHERE k.key = up.src
                                   AND k.principal_type <> ALL (v_whole) OFFSET 0) k
               ON CONFLICT DO NOTHING RETURNING key)
      SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    END IF;
    DELETE FROM authz_int.sync_moved m WHERE m.txid = v_tx;
    -- the principals who are somebody now: their keys, worked out whole
    IF cardinality(v_came) > 0 THEN
    WITH made AS (INSERT INTO authz_sync.keys SELECT 'user', f.o_id, f.o_key FROM authz_int."sync_keys:user"(ARRAY(
                    SELECT substr(c, 6) FROM unnest(v_came) c WHERE left(c, 5) = 'user:')) f
                  ON CONFLICT DO NOTHING RETURNING key)
    SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    WITH made AS (INSERT INTO authz_sync.keys SELECT 'integration', f.o_id, f.o_key FROM authz_int."sync_keys:integration"(ARRAY(
                    SELECT substr(c, 13) FROM unnest(v_came) c WHERE left(c, 12) = 'integration:')) f
                  ON CONFLICT DO NOTHING RETURNING key)
    SELECT v_keys || coalesce(array_agg(DISTINCT z.key), '{}') INTO v_keys FROM made z;
    END IF;
  END IF;
  -- rows whose readers were worked out from a key someone gained or lost, and what reads them
  IF cardinality(v_keys) > 0 THEN
    INSERT INTO authz_int.sync_todo (txid, type, id, round)
    SELECT DISTINCT v_tx, x.object_type, x.object_id, v_round + 1 FROM authz_sync.expanded x WHERE x.key IN (SELECT unnest(v_keys))
    ON CONFLICT DO NOTHING;
    IF FOUND THEN
      v_round := authz_int.sync_spread(v_tx, v_round + 1);
    END IF;
  END IF;
  -- ticket's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'ticket' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "hd"."tickets" x UNION SELECT x."id"::text FROM authz_sync."ticket__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'ticket') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'ticket') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:ticket"(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."ticket__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."ticket__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."ticket__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'ticket' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'ticket', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  -- comment's readers
  v_ids := CASE WHEN EXISTS (SELECT 1 FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'comment' AND x.id = '*') THEN ARRAY(SELECT x."id"::text FROM "hd"."comments" x UNION SELECT x."id"::text FROM authz_sync."comment__readers" x UNION SELECT x.object_id FROM authz_sync.expanded x WHERE x.object_type = 'comment') ELSE ARRAY(SELECT x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.type = 'comment') END;
  -- (a batch of objects at a time, which a comparison holds in memory; what is there compared first, by the key's
  -- index: only the rows that change are visited)
  FOR v_from IN 1 .. coalesce(cardinality(v_ids), 0) BY 10000 LOOP
    v_part := v_ids[v_from : v_from + 9999];
    WITH fresh AS MATERIALIZED (SELECT f.o_id, f.o_key, f.o_dep FROM authz_int."sync:comment"(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) f),
    there AS MATERIALIZED (SELECT x."id" AS id, x.key FROM authz_sync."comment__readers" x
                           WHERE x."id" IN (SELECT unnest(ARRAY(SELECT v::uuid FROM unnest(v_part) v WHERE pg_catalog.pg_input_is_valid(v, 'uuid'))) AS id)),
    stale AS (SELECT s.id, s.key FROM there s EXCEPT SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep),
    added AS (SELECT f.o_id, f.o_key FROM fresh f WHERE NOT f.o_dep EXCEPT SELECT s.id, s.key FROM there s),
    gone AS (DELETE FROM authz_sync."comment__readers" x USING stale s WHERE x."id" = s.id AND x.key = s.key
             RETURNING 1),
    made AS (INSERT INTO authz_sync."comment__readers" SELECT a.o_id, a.o_key FROM added a
             ORDER BY 1, 2 ON CONFLICT DO NOTHING RETURNING 1),
    gone_from AS (DELETE FROM authz_sync.expanded x WHERE x.object_type = 'comment' AND x.object_id IN (SELECT unnest(v_part))
             AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.o_dep AND f.o_id::text = x.object_id AND f.o_key = x.key) RETURNING 1),
    made_from AS (INSERT INTO authz_sync.expanded SELECT 'comment', f.o_id::text, f.o_key FROM fresh f WHERE f.o_dep ON CONFLICT DO NOTHING RETURNING 1)
    SELECT count(*) INTO v_n FROM (SELECT 1 FROM gone UNION ALL SELECT 1 FROM made UNION ALL SELECT 1 FROM gone_from
                                   UNION ALL SELECT 1 FROM made_from) z;
  END LOOP;
  -- the next start or end of a share on what was worked out, after now(), when authz.sync_tick() works it out again
  -- (the work reads the shares as of the transaction's start: one that starts or ends while it is open, and a tick
  -- meanwhile, which can't see what it hasn't committed, are worked out again at the next tick)
  v_ids := ARRAY(SELECT DISTINCT x.type FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id = '*');
  WITH w AS MATERIALIZED (SELECT x.type, x.id FROM authz_int.sync_todo x WHERE x.txid = v_tx AND x.id <> '*'
                          AND x.type <> ALL (v_ids)),
  fresh AS MATERIALIZED (
    SELECT w.type, w.id, b.at FROM w
    CROSS JOIN LATERAL (SELECT min(v.at) AS at FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
                        WHERE g.object_type = w.type AND g.object_id = w.id AND v.at > now()) b
    WHERE b.at IS NOT NULL
    UNION ALL
    SELECT g.object_type, g.object_id, min(v.at) FROM authz.shares g CROSS JOIN LATERAL (VALUES (g.starts_at), (g.expires_at)) v(at)
    WHERE g.object_type = ANY (v_ids) AND v.at > now() GROUP BY g.object_type, g.object_id),
  gone AS (DELETE FROM authz_sync.due d USING w WHERE d.object_type = w.type AND d.object_id = w.id
           AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.type = d.object_type AND f.id = d.object_id) RETURNING 1),
  gone_all AS (DELETE FROM authz_sync.due d WHERE d.object_type = ANY (v_ids)
           AND NOT EXISTS (SELECT 1 FROM fresh f WHERE f.type = d.object_type AND f.id = d.object_id) RETURNING 1)
  INSERT INTO authz_sync.due SELECT f.type, f.id, f.at FROM fresh f
  ON CONFLICT (object_type, object_id) DO UPDATE SET at = EXCLUDED.at WHERE authz_sync.due.at <> EXCLUDED.at;
  DELETE FROM authz_int.sync_todo x WHERE x.txid = v_tx;
END $f$;

-- the index worked out again where what it is worked out by changed (p_hash), or all of it (p_force); by difference
CREATE OR REPLACE FUNCTION authz_int.sync_refresh(p_hash text, p_force boolean DEFAULT false) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF p_force OR NOT EXISTS (SELECT 1 FROM authz_sync.definitions d WHERE d.name = 'index' AND d.hash = p_hash) THEN
    -- what this policy no longer keeps
  DELETE FROM authz_sync.groups g WHERE left(g.grp, strpos(g.grp, ':')) <> ALL (ARRAY['team#member:', 'team#oversee:']::text[]);
    DELETE FROM authz_sync.keys k WHERE k.principal_type <> ALL (ARRAY['user', 'integration']::text[]);
    DELETE FROM authz_sync.expanded x WHERE x.object_type <> ALL (ARRAY['ticket', 'comment']::text[]);
    DELETE FROM authz_sync.due d WHERE d.object_type <> ALL (ARRAY['comment', 'customer_org', 'integration', 'team', 'ticket', 'user', 'workspace']::text[]);
    INSERT INTO authz_int.sync_todo (txid, type, id) SELECT txid_current(), x, '*' FROM unnest(ARRAY['comment', 'customer_org', 'integration', 'team', 'ticket', 'user', 'workspace']::text[]) x ON CONFLICT DO NOTHING;
  END IF;
  PERFORM authz_int.sync_process();
  IF p_hash IS NOT NULL THEN
    INSERT INTO authz_sync.definitions VALUES ('index', p_hash) ON CONFLICT (name) DO UPDATE SET hash = EXCLUDED.hash;
  END IF;
END $f$;

-- Shares that start or end later change who reads their objects with no write: SELECT authz.sync_tick() works out
-- again the readers of the objects whose next share start or end (authz_sync.due, as of when their readers were last
-- worked out) has passed, and says how many shares. Schedule it (pg_cron, the app's jobs) as often as a share that
-- ends should leave the engines' clients
CREATE OR REPLACE FUNCTION authz.sync_tick() RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_to timestamptz := now();
  n bigint;
BEGIN
  SELECT count(*) INTO n FROM authz_sync.due d
  JOIN authz.shares g ON g.object_type = d.object_type AND g.object_id = d.object_id
  WHERE d.at <= v_to AND ((g.expires_at >= d.at AND g.expires_at <= v_to) OR (g.starts_at >= d.at AND g.starts_at <= v_to));
  PERFORM authz_int.sync_dirty(d.object_type, array_agg(d.object_id)) FROM authz_sync.due d WHERE d.at <= v_to
  GROUP BY d.object_type;
  RETURN n;
END $f$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

SELECT authz_int.sync_refresh('eb84edd59173787a40dea53fd6dfcb89');
DO $sw$
DECLARE n bigint; m bigint;
BEGIN
  SELECT count(*) FILTER (WHERE g.caveat IS NOT NULL), count(*) FILTER (WHERE g.subject_type = 'link') INTO n, m
  FROM authz.shares g WHERE (g.object_type = 'ticket' AND g.relation = 'responder') OR (g.object_type = 'ticket' AND g.relation = 'cc') OR (g.object_type = 'ticket' AND g.relation LIKE 'role:%');
  IF n > 0 THEN
    RAISE WARNING '% shares with a caveat give nothing through the sync index: a caveat is checked at each request, with what it says', n;
  END IF;
  IF m > 0 THEN
    RAISE WARNING '% share links give nothing through the sync index: a synced client is a principal, without links', m;
  END IF;
END $sw$;

-- The sync role reads the index, and nothing else rowstile keeps
DO $sr$
DECLARE v_sync oid := to_regrole('"hd_electric"'); v_app oid := to_regrole('"hd_app"'); v_cols text;
BEGIN
  IF v_sync IS NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric does not exist [AZ808]'
      USING HINT = 'make it for the engine: CREATE ROLE hd_electric LOGIN REPLICATION BYPASSRLS, then apply again';
  END IF;
  IF pg_catalog.pg_has_role(v_sync, CURRENT_USER, 'MEMBER') THEN
    RAISE EXCEPTION 'the sync role hd_electric is the role that applies the policy (%), or a member of it [AZ808]', CURRENT_USER
      USING HINT = 'the engine connects as a role of its own, which owns nothing of the database';
  END IF;
  IF v_app IS NOT NULL AND (pg_catalog.pg_has_role(v_sync, v_app, 'MEMBER') OR pg_catalog.pg_has_role(v_app, v_sync, 'MEMBER')) THEN
    RAISE EXCEPTION 'the sync role hd_electric and the app role hd_app are one another''s members: the app would read every row [AZ808]'
      USING HINT = 'the engine connects as a role of its own, which the app role is not a member of, nor it of the app role';
  END IF;
  SELECT pg_catalog.string_agg(m.tbl || '.' || m.col, ', ' ORDER BY m.tbl, m.col) INTO v_cols FROM authz_int.masked_columns m
  WHERE pg_catalog.has_column_privilege(v_sync, m.tbl, m.col, 'SELECT');
  IF v_cols IS NOT NULL THEN
    RAISE EXCEPTION 'the sync role hd_electric may read masked columns: % [AZ809]', v_cols
      USING HINT = 'it reads every row, so a masked column would reach every client: revoke SELECT on the table, grant the other columns (GRANT SELECT (id, name) ON ...), then apply again';
  END IF;
END $sr$;
GRANT USAGE ON SCHEMA authz_sync TO "hd_electric";
GRANT SELECT ON ALL TABLES IN SCHEMA authz_sync TO "hd_electric";

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"hd_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."customer_org__member"', 'authz_int."customer_org__view"', 'authz_int."team__lead"', 'authz_int."team__manage"', 'authz_int."team__member"', 'authz_int."team__oversee"', 'authz_int."team__view"', 'authz_int."ticket__cc"', 'authz_int."ticket__reply"', 'authz_int."ticket__responder"', 'authz_int."ticket__roles:work"', 'authz_int."ticket__view"', 'authz_int."ticket__work"', 'authz_int."user__org_tickets"', 'authz_int."user__self"', 'authz_int."workspace__admin"', 'authz_int."workspace__agent"', 'authz_int."workspace__connected"', 'authz_int."workspace__manage"', 'authz_int."workspace__member"', 'authz_int."workspace__view"', 'authz_int."workspace__work"', 'authz_int."workspace__work_all"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"hd_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"hd_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"hd.comments:delete:items"', '"hd.comments:delete:why"', '"hd.comments:insert:items"', '"hd.comments:insert:refuse"', '"hd.comments:insert:why"', '"hd.comments:rules:explain"', '"hd.comments:update:items"', '"hd.comments:update:refuse"', '"hd.comments:update:why"', '"hd.customer_orgs:column id, workspace_id:items"', '"hd.customer_orgs:column id, workspace_id:why"', '"hd.customer_orgs:delete:items"', '"hd.customer_orgs:delete:why"', '"hd.customer_orgs:insert:items"', '"hd.customer_orgs:insert:refuse"', '"hd.customer_orgs:insert:why"', '"hd.customer_orgs:rules:explain"', '"hd.customer_orgs:update:items"', '"hd.customer_orgs:update:refuse"', '"hd.customer_orgs:update:why"', '"hd.integrations:column id, workspace_id:items"', '"hd.integrations:column id, workspace_id:why"', '"hd.integrations:delete:items"', '"hd.integrations:delete:why"', '"hd.integrations:insert:items"', '"hd.integrations:insert:refuse"', '"hd.integrations:insert:why"', '"hd.integrations:rules:explain"', '"hd.integrations:update:items"', '"hd.integrations:update:refuse"', '"hd.integrations:update:why"', '"hd.support_access:delete:items"', '"hd.support_access:delete:why"', '"hd.support_access:insert:items"', '"hd.support_access:insert:refuse"', '"hd.support_access:insert:why"', '"hd.support_access:rules:explain"', '"hd.support_access:update:items"', '"hd.support_access:update:refuse"', '"hd.support_access:update:why"', '"hd.team_leads:delete:items"', '"hd.team_leads:delete:why"', '"hd.team_leads:insert:items"', '"hd.team_leads:insert:refuse"', '"hd.team_leads:insert:why"', '"hd.team_leads:rules:explain"', '"hd.team_leads:update:items"', '"hd.team_leads:update:refuse"', '"hd.team_leads:update:why"', '"hd.team_members:delete:items"', '"hd.team_members:delete:why"', '"hd.team_members:insert:items"', '"hd.team_members:insert:refuse"', '"hd.team_members:insert:why"', '"hd.team_members:rules:explain"', '"hd.team_members:update:items"', 